import * as T from './vendor/three.js';
const $=s=>document.querySelector(s);
export function createDayNight({scene,renderer,camera,sky,sun,ambient,windowMaterials}){
 let hour=16.5,running=true,uiClock=-1;
 const skyMaterial=new T.ShaderMaterial({side:T.BackSide,depthWrite:false,fog:false,uniforms:{dayMap:{value:sky.material.map},daylight:{value:1},twilight:{value:0},sunDirection:{value:new T.Vector3()},topColor:{value:new T.Color('#050b23')},horizonColor:{value:new T.Color('#253b60')}},vertexShader:`varying vec2 vUv;varying vec3 vDirection;void main(){vUv=uv;vDirection=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,fragmentShader:`uniform sampler2D dayMap;uniform float daylight;uniform float twilight;uniform vec3 sunDirection;uniform vec3 topColor;uniform vec3 horizonColor;varying vec2 vUv;varying vec3 vDirection;void main(){vec3 dir=normalize(vDirection);float h=pow(max(0.0,dir.y),0.5);vec3 night=mix(horizonColor,topColor,h);vec3 day=texture2D(dayMap,vUv).rgb;vec3 color=mix(night,day,daylight);float sunset=pow(max(0.0,dot(normalize(vec3(dir.x,0.,dir.z)),normalize(vec3(sunDirection.x,0.,sunDirection.z)))),3.0)*exp(-max(0.0,dir.y)*6.0);color=mix(color,vec3(0.91,0.34,0.19),sunset*twilight*.7);gl_FragColor=vec4(color,1.0);
#include <tonemapping_fragment>
#include <colorspace_fragment>
}`});sky.material=skyMaterial;
 const moonLight=new T.DirectionalLight('#a9c9ff',.35);scene.add(moonLight);
 const sunDisc=new T.Mesh(new T.SphereGeometry(85,12,8),new T.MeshBasicMaterial({color:'#fff0c7',fog:false,toneMapped:false}));
 const moonDisc=new T.Mesh(new T.SphereGeometry(63,12,8),new T.MeshBasicMaterial({color:'#dce9ff',fog:false,toneMapped:false}));scene.add(sunDisc,moonDisc);
 const starPositions=[];let seed=1701;const random=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};for(let i=0;i<650;i++){let az=random()*Math.PI*2,y=.03+random()*.97,r=Math.sqrt(1-y*y);starPositions.push(Math.cos(az)*r*9200,y*9200,Math.sin(az)*r*9200)}const starGeometry=new T.BufferGeometry();starGeometry.setAttribute('position',new T.Float32BufferAttribute(starPositions,3));const stars=new T.Points(starGeometry,new T.PointsMaterial({color:'#dfebff',size:9,sizeAttenuation:true,transparent:true,opacity:0,depthWrite:false,fog:false,toneMapped:false}));stars.renderOrder=-5;scene.add(stars);
 const slider=$('#time-slider'),toggle=$('#time-running'),readout=$('#time-value'),phase=$('#time-phase');
 function sync(){const minutes=Math.floor(hour*60)%1440;const label=String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');readout.textContent=label;$('#game-clock').textContent=label+' · VALLEY TIME';slider.value=minutes;slider.setAttribute('aria-valuetext',label);phase.textContent=hour<5||hour>=20?'NIGHT':hour<8?'DAWN':hour<16.5?'DAYLIGHT':hour<18?'AFTERNOON':'DUSK';toggle.textContent=running?'Ⅱ':'▶';toggle.setAttribute('aria-label',running?'Pause time':'Resume time');toggle.setAttribute('aria-pressed',String(!running))}
 toggle.onclick=()=>{running=!running;sync()};slider.addEventListener('input',()=>{hour=Number(slider.value)/60;running=false;sync();update(0)});
 document.querySelectorAll('[data-hour]').forEach(button=>button.onclick=()=>{hour=Number(button.dataset.hour);sync();update(0)});
 function skip(){const phases=[5.5,12,18.5,23];hour=phases.find(h=>h>hour+.1)??phases[0];sync();update(0)}
 function update(dt,advance=true){if(running&&advance)hour=(hour+dt/30)%24;const angle=(hour-6)/24*Math.PI*2,altitude=Math.sin(angle),day=T.MathUtils.smoothstep(altitude,-.35,.3),night=1-T.MathUtils.smoothstep(altitude,-.4,.05),twilight=Math.exp(-Math.pow(altitude/.24,2));const direction=new T.Vector3(Math.cos(angle),altitude,-.4).normalize();sun.position.copy(direction).multiplyScalar(1000);sun.intensity=2.1*T.MathUtils.smoothstep(altitude,-.02,.3);sun.color.set('#fff9ee').lerp(new T.Color('#ffac77'),twilight*.7);ambient.intensity=T.MathUtils.lerp(.2,1.85,day);ambient.color.set('#6c8fce').lerp(new T.Color('#e2f1ff'),day);ambient.groundColor.set('#1e3047').lerp(new T.Color('#a5b5aa'),day);moonLight.position.copy(direction).multiplyScalar(-1000);moonLight.intensity=.45*night;skyMaterial.uniforms.topColor.value.set('#050b23').lerp(new T.Color('#292342'),twilight*.7);skyMaterial.uniforms.horizonColor.value.set('#253b60').lerp(new T.Color('#9a6b88'),twilight*.65);skyMaterial.uniforms.daylight.value=day;skyMaterial.uniforms.twilight.value=twilight;skyMaterial.uniforms.sunDirection.value.copy(direction);scene.fog.color.set('#182a46').lerp(new T.Color('#c0dce8'),day).lerp(new T.Color('#c78e91'),twilight*.3);scene.fog.near=T.MathUtils.lerp(300,800,day);renderer.toneMappingExposure=T.MathUtils.lerp(1.22,1.05,day);sunDisc.position.copy(direction).multiplyScalar(8500).add(camera.position);sunDisc.visible=altitude>-.04;sunDisc.material.color.set('#fff2cc').lerp(new T.Color('#ffad70'),twilight);moonDisc.position.copy(direction).multiplyScalar(-8500).add(camera.position);moonDisc.visible=altitude<.04;stars.material.opacity=night*.85;stars.position.copy(camera.position);for(const material of windowMaterials)material.emissiveIntensity=night*1.7;const now=Math.floor(hour*60);if(now!==uiClock){uiClock=now;sync()}}
 update(0);return{update,skip};
}
